# ═══════════════════════════════════════════════════════
# Git integration
# ═══════════════════════════════════════════════════════

def get_git_diff(filepath):
    """Get git diff for a file, returning dict of line_num -> change_type."""
    try:
        result = subprocess.run(
            ['git', 'diff', '--unified=0', '--no-color', 'HEAD', '--', filepath],
            capture_output=True, text=True, cwd=os.path.dirname(os.path.abspath(filepath)) or '.'
        )
        if result.returncode != 0:
            # Try without HEAD (for new files)
            result = subprocess.run(
                ['git', 'diff', '--unified=0', '--no-color', '--', filepath],
                capture_output=True, text=True, cwd=os.path.dirname(os.path.abspath(filepath)) or '.'
            )
        if result.returncode != 0:
            return {}
    except (FileNotFoundError, subprocess.SubprocessError):
        return {}

    changes = {}
    current_new_line = 0

    for line in result.stdout.split('\n'):
        if line.startswith('@@'):
            # @@ -old_start,old_count +new_start,new_count @@
            m = re.match(r'@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@', line)
            if m:
                new_start = int(m.group(3))
                new_count = int(m.group(4)) if m.group(4) is not None else 1
                old_count = int(m.group(2)) if m.group(2) is not None else 1
                current_new_line = new_start
        elif line.startswith('+') and not line.startswith('+++'):
            changes[current_new_line] = 'added'
            current_new_line += 1
        elif line.startswith('-') and not line.startswith('---'):
            # Deleted line - mark previous new line as modified
            if current_new_line in changes and changes[current_new_line] == 'added':
                changes[current_new_line] = 'modified'
            elif current_new_line > 0:
                # The line at current position was modified
                changes[current_new_line] = 'modified'
        elif line.startswith(' '):
            current_new_line += 1

    return changes

def get_git_diff_v2(filepath):
    """Get git diff for a file using proper diff parsing."""
    try:
        abs_path = os.path.abspath(filepath)
        work_dir = os.path.dirname(abs_path)

        result = subprocess.run(
            ['git', 'diff', '--unified=0', '--no-color', 'HEAD', '--', abs_path],
            capture_output=True, text=True, cwd=work_dir
        )
        if result.returncode != 0 or not result.stdout.strip():
            result = subprocess.run(
                ['git', 'diff', '--unified=0', '--no-color', '--', abs_path],
                capture_output=True, text=True, cwd=work_dir
            )
        if not result.stdout.strip():
            return {}
    except (FileNotFoundError, subprocess.SubprocessError):
        return {}

    changes = {}
    in_hunk = False
    new_line = 0

    for line in result.stdout.split('\n'):
        if line.startswith('@@'):
            m = re.match(r'@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@', line)
            if m:
                new_line = int(m.group(3))
                in_hunk = True
        elif in_hunk:
            if line.startswith('+') and not line.startswith('+++'):
                if new_line not in changes:
                    changes[new_line] = 'added'
                new_line += 1
            elif line.startswith('-') and not line.startswith('---'):
                # This line was deleted from old - mark the new_line as modified
                if new_line in changes and changes[new_line] == 'added':
                    changes[new_line] = 'modified'
                elif new_line not in changes:
                    # The previous line (new_line - 1? or current?) was modified
                    # Actually in a replacement: first comes removes, then adds
                    # But with --unified=0, we see -old +new pairs
                    pass
            elif line.startswith(' '):
                new_line += 1

    return changes

