        new_adds = 0

        for line in hunk_lines:
            if not line:
                continue
            if line.startswith('+') and not line.startswith('+++'):
                new_adds += 1
            elif line.startswith('-') and not line.startswith('---'):
                old_removes += 1

        # If both removes and adds: lines are modified
        # If only adds: lines are added
        # If only removes: deletion (nothing to mark)
        new_line = new_start
        removes_in_progress = 0
        adds_in_progress = 0

        for line in hunk_lines:
            if not line:
                continue
            if line.startswith('+') and not line.startswith('+++'):
                if removes_in_progress > 0:
                    changes[new_line] = 'modified'
                    removes_in_progress -= 1
                else:
                    changes[new_line] = 'added'
                new_line += 1
            elif line.startswith('-') and not line.startswith('---'):
