            # @@ -old_start,old_count +new_start,new_count @@
            m = re.match(r'@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@', line)
            if m:
                new_start = int(m.group(3))
                new_count = int(m.group(4)) if m.group(4) is not None else 1
                old_count = int(m.group(2)) if m.group(2) is not None else 1
                current_new_line = new_start
        elif line.startswith('+') and not line.startswith('+++'):
            changes[current_new_line] = 'added'
            current_new_line += 1
        elif line.startswith('-') and not line.startswith('---'):
            # Deleted line - mark previous new line as modified
            if current_new_line in changes and changes[current_new_line] == 'added':
                changes[current_new_line] = 'modified'
            elif current_new_line > 0:
                # The line at current position was modified
                changes[current_new_line] = 'modified'
        elif line.startswith(' '):
