def get_git_changes(filepath):
    """
    Parse git diff to get per-line change markers.
    Returns dict: line_number (1-based) -> 'added' | 'modified'
    """
    try:
        abs_path = os.path.abspath(filepath)
        work_dir = os.path.dirname(abs_path)
        if not work_dir:
            work_dir = '.'

        result = subprocess.run(
            ['git', 'diff', '--unified=0', '--no-color', 'HEAD', '--', abs_path],
            capture_output=True, text=True, cwd=work_dir
        )
        if not result.stdout.strip():
            result = subprocess.run(
                ['git', 'diff', '--unified=0', '--no-color', '--', abs_path],
                capture_output=True, text=True, cwd=work_dir
            )
        output = result.stdout
    except (FileNotFoundError, subprocess.SubprocessError):
        return {}

    if not output.strip():
        return {}

    changes = {}

    # Parse hunks
    for hunk_match in re.finditer(r'@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@.*?(?=@@|\Z)', output, re.DOTALL):
        old_start = int(hunk_match.group(1))
        old_count = int(hunk_match.group(2)) if hunk_match.group(2) is not None else 1
        new_start = int(hunk_match.group(3))
        new_count = int(hunk_match.group(4)) if hunk_match.group(4) is not None else 1

        hunk_lines = hunk_match.group(0).split('\n')[1:]  # skip @@ line

        new_line = new_start
        old_removes = 0
        new_adds = 0

        for line in hunk_lines:
            if not line:
                continue
            if line.startswith('+') and not line.startswith('+++'):
                new_adds += 1
            elif line.startswith('-') and not line.startswith('---'):
                old_removes += 1

        # If both removes and adds: lines are modified
        # If only adds: lines are added
        # If only removes: deletion (nothing to mark)
        new_line = new_start
        removes_in_progress = 0
        adds_in_progress = 0

        for line in hunk_lines:
            if not line:
                continue
            if line.startswith('+') and not line.startswith('+++'):
                if removes_in_progress > 0:
                    changes[new_line] = 'modified'
                    removes_in_progress -= 1
                else:
                    changes[new_line] = 'added'
                new_line += 1
            elif line.startswith('-') and not line.startswith('---'):
                removes_in_progress += 1

    return changes

