    if len(parts) == 2:
        start_str, end_str = parts

        # Handle N::C pattern (empty middle)
        # This doesn't apply with 2 parts

        if start_str.startswith('-') and not end_str:
            # -N: -> last N lines
            try:
                n = int(start_str)  # negative
                if total_lines is not None:
