        if start_str == '':
            start = 1
        elif start_str.startswith('-'):
            try:
                n = int(start_str)
                if total_lines is not None:
                    start = total_lines + n + 1
                else:
                    start = start_str  # defer
            except ValueError:
                return None
        else:
            try:
                start = int(start_str)
            except ValueError:
                return None

        # Parse end
        if end_str == '':
            end = None  # to end of file
        elif end_str.startswith('+'):
            try:
                offset = int(end_str[1:])
                if isinstance(start, int):
                    end = start + offset
                else:
                    return None
            except ValueError:
                return None
        elif end_str.startswith('-'):
            try:
                n = int(end_str)
                if total_lines is not None:
                    end = total_lines + n + 1
                else:
                    end = end_str  # defer
            except ValueError:
                return None
        else:
            try:
                end = int(end_str)
            except ValueError:
                return None

        return (start, end)

    if len(parts) == 3:
        start_str, end_str, ctx_str = parts

        try:
            ctx = int(ctx_str) if ctx_str else 0
        except ValueError:
            return None

        if end_str == '':
            # N::C -> center around N
            try:
                n = int(start_str)
                return (n - ctx, n + ctx)
            except ValueError:
                return None
        else:
            # N:M:C -> range with context
            try:
                n_start = int(start_str)
                n_end = int(end_str)
                return (n_start - ctx, n_end + ctx)
            except ValueError:
                return None

    return None

