        if isinstance(end, str) and end.startswith('-'):
            if total_lines is not None:
                end = total_lines + int(end) + 1
            else:
                end = total_lines or 999999

        if start is None:
            start = 1
        if end is None:
            end = total_lines or 999999999

        if start <= line_num <= end:
            return True

    return False

