# Word wrapping
# ═══════════════════════════════════════════════════════

def wrap_line(text, width, mode='auto'):
    """Wrap a line to fit within width chars."""
    if mode == 'never' or mode == 'auto':
        return [text]

    if len(text) <= width:
        return [text]

    if mode == 'character':
        lines = []
        while len(text) > width:
            lines.append(text[:width])
            text = text[width:]
        if text:
            lines.append(text)
        return lines

    if mode == 'word':
        # Word-wrap
        result = textwrap.wrap(text, width, break_long_words=True, break_on_hyphens=False)
        if not result:
            return ['']
        return result

    return [text]

