# Main output renderer
# ═══════════════════════════════════════════════════════

class BatRenderer:
    def __init__(self, opts):
        self.opts = opts
        self.term_width = opts.terminal_width
        self.use_color = opts.use_color
        self.show_numbers = opts.show_numbers
        self.show_changes = opts.show_changes
        self.show_grid = opts.show_grid
        self.show_header_filename = opts.show_header_filename
        self.show_header_filesize = opts.show_header_filesize
        self.show_snip = opts.show_snip
        self.show_rule = opts.show_rule

        # Gutter width calculation
        # numbers: max(4, len(str(total_lines))) + 1 space = dynamic
        # changes: 1 char + 1 space = 2 chars
        # Base gutter: (4+1 if numbers else 0) + (2 if changes else 0)
        self.base_gutter = 0
        if self.show_numbers:
            self.base_gutter += 5  # 4 number chars + 1 space
        if self.show_changes:
            self.base_gutter += 2  # 1 change char + 1 space

    def get_gutter_width(self, max_line_num):
        """Get actual gutter width based on max line number."""
        w = 0
        if self.show_numbers:
            num_width = max(4, len(str(max_line_num)))
            w += num_width + 1
        if self.show_changes:
            w += 2
        return w

    def color(self, text, code):
        """Wrap text in ANSI color if colors enabled."""
        if self.use_color:
            return f"\x1b[{code}m{text}\x1b[0m"
        return text

    def color_num(self, text):
        """Color for line numbers."""
        return self.color(text, "38;5;246")

    def color_separator(self, text):
        """Color for grid separators."""
        return self.color(text, "38;5;246")

    def color_change_added(self, text):
        """Color for added line marker."""
        return self.color(text, "32")

    def color_change_modified(self, text):
        """Color for modified line marker."""
