def get_terminal_width(width_arg=None):
    """Get the terminal width."""
    # Check BAT_WIDTH env var
    bat_width = os.environ.get('BAT_WIDTH')

    # Process width argument
    effective_width = None

    if width_arg:
        w = str(width_arg)
        if w.startswith('+'):
            offset = int(w[1:])
            try:
                actual = os.get_terminal_size().columns
            except:
                actual = 80
            effective_width = actual + offset
        elif w.startswith('-'):
            offset = int(w[1:])
            try:
                actual = os.get_terminal_size().columns
            except:
                actual = 80
            effective_width = actual - offset
        else:
            effective_width = int(w)

    if bat_width:
        w = bat_width.strip()
        if w.startswith('+'):
            try:
                actual = os.get_terminal_size().columns
            except:
                actual = 80
            effective_width = actual + int(w[1:])
        elif w.startswith('-'):
            try:
                actual = os.get_terminal_size().columns
            except:
                actual = 80
            effective_width = actual - int(w[1:])
        else:
            try:
                effective_width = int(w)
            except:
                pass

    if effective_width is not None:
        return max(1, effective_width)

    # Try to get actual terminal size
    try:
        return os.get_terminal_size().columns
    except:
        return 80  # default

