    """Process and output a single file."""

    output_lines = []  # We'll collect and write

    # Detect language
    language = None
    if opts.language:
        language = opts.language
    elif display_name:
        language = detect_language_from_filename(display_name, opts.map_syntax)
    elif filepath and filepath != '-':
        language = detect_language_from_filename(filepath, opts.map_syntax)

    if language is None and opts.fallback_syntax:
        language = opts.fallback_syntax

    if language is None:
        language = detect_language_from_content(content_bytes)

    # Process show-all
    if opts.show_all:
        content_str = process_show_all(content_bytes, opts.nonprintable_notation, 
                                        opts.tab_width if opts.tab_width else 4)
    else:
        # Decode content
        try:
            content_str = content_bytes.decode('utf-8', errors='replace')
        except:
            content_str = content_bytes.decode('latin-1', errors='replace')

        # Strip ANSI if requested
        if opts.strip_ansi == 'always':
            content_str = strip_ansi(content_str)
        elif opts.strip_ansi == 'auto' and language not in ('Plain Text', None):
            content_str = strip_ansi(content_str)

    # Tab expansion (only when color is active)
    if opts.use_color and opts.tab_width and opts.tab_width > 0 and not opts.show_all:
        content_str = content_str.replace('\t', ' ' * opts.tab_width)

    # Split into lines (preserve whether last line has newline)
    if content_str.endswith('\n'):
        lines = content_str[:-1].split('\n')
        has_final_newline = True
    else:
        lines = content_str.split('\n')
        has_final_newline = False

    # Apply squeeze-blank
    if opts.squeeze_blank:
        limit = opts.squeeze_limit if opts.squeeze_limit > 0 else 1
        new_lines = []
        blank_count = 0
        for line in lines:
            if line.strip() == '':
                blank_count += 1
                if blank_count <= limit:
                    new_lines.append(line)
            else:
                blank_count = 0
                new_lines.append(line)
        lines = new_lines

    total_lines = len(lines)

    # Parse line ranges
    parsed_ranges = []
    if opts.line_ranges:
        for rspec in opts.line_ranges:
            r = parse_line_range(rspec, total_lines)
            if r:
                # Resolve deferred negative values
                start, end = r
                if isinstance(start, str) and start.startswith('-'):
                    start = total_lines + int(start) + 1
                if isinstance(end, str) and end.startswith('-'):
                    end = total_lines + int(end) + 1
                if start is None:
                    start = 1
                if end is None:
                    end = total_lines
                parsed_ranges.append((max(1, int(start)), int(end) if end else total_lines))

    # Apply diff filtering
    diff_lines = set()
    if opts.diff and git_changes:
        context = opts.diff_context
        for line_num, change_type in git_changes.items():
            for i in range(max(1, line_num - context), min(total_lines, line_num + context) + 1):
                diff_lines.add(i)

    # Get syntax highlighting if needed
    highlighted_lines = None
    if opts.use_color and language and language != 'Plain Text':
        try:
            full_content = '\n'.join(lines)
            if has_final_newline:
                full_content += '\n'
            hl_result = highlight_content(full_content, language, opts.theme, 
                                           display_name or filepath)
            if hl_result:
                hl_result = convert_pygments_to_bat_reset(hl_result)
                # Remove trailing newline added by pygments
                if hl_result.endswith('\n'):
                    hl_result = hl_result[:-1]
                highlighted_lines = hl_result.split('\n')
        except Exception:
            highlighted_lines = None

    # Calculate gutter width
    num_width = max(4, len(str(total_lines)))
    gutter_w = 0
    if renderer.show_numbers:
        gutter_w += num_width + 1
    if renderer.show_changes:
        gutter_w += 2

    # Parse highlight lines
    hl_lines = set()
    if opts.highlight_lines:
        for hl_spec in opts.highlight_lines:
            r = parse_line_range(hl_spec, total_lines)
            if r:
                start, end = r
                if start is None:
                    start = 1
                if end is None:
                    end = total_lines
                for i in range(int(start), int(end) + 1):
                    hl_lines.add(i)

    # Decorations
    needs_decoration = renderer.show_numbers or renderer.show_changes or renderer.show_grid or \
                       renderer.show_header_filename or renderer.show_header_filesize

    # === Render header ===
    if needs_decoration and (renderer.show_header_filename or renderer.show_header_filesize or renderer.show_grid):
        header_lines = renderer.render_header(
            display_name or filepath, 
            file_size,
            is_stdin
        )
        for hl in header_lines:
            output_lines.append(hl)

    # === Render grid separator after header (if grid) ===
    if renderer.show_grid and (renderer.show_header_filename or renderer.show_header_filesize):
        sep = renderer.render_grid_separator(gutter_w, BOX_CR)
        output_lines.append(sep)
    elif renderer.show_grid and not (renderer.show_header_filename or renderer.show_header_filesize):
        # No header - just top grid line
        pass  # Already in render_header with BOX_TM

    # === Render content ===
    prev_in_range = True
    first_range_line = True

    for i, line in enumerate(lines):
        line_num = i + 1

        # Check if line is in range
        if parsed_ranges:
            in_range = lines_in_range(line_num, parsed_ranges, total_lines)
        else:
            in_range = True

        # Apply diff filter
        if opts.diff and git_changes:
            if line_num not in diff_lines:
                if in_range and not prev_in_range:
                    first_range_line = True
                prev_in_range = in_range
                continue

        if not in_range:
            if renderer.show_snip and prev_in_range and not first_range_line:
                snip = renderer.render_snip(gutter_w, total_lines)
                output_lines.append(snip)
            prev_in_range = False
            continue

        # Show snip before this range if needed
        if renderer.show_snip and not prev_in_range:
            snip = renderer.render_snip(gutter_w, total_lines)
            output_lines.append(snip)

        prev_in_range = True
        first_range_line = False

        # Get change type
        change_type = None
        if git_changes:
            change_type = git_changes.get(line_num)

        # Get highlighted text for this line
        hl_text = None
        if highlighted_lines and i < len(highlighted_lines):
            hl_text = highlighted_lines[i]

        # Apply highlight line background
        is_hl = line_num in hl_lines

        if needs_decoration:
            # Build decorated line
            parts = []

            if renderer.show_numbers:
                num_str = str(line_num).rjust(num_width)
                if is_hl:
                    parts.append(renderer.color_num(num_str))
                else:
                    parts.append(renderer.color_num(num_str))
                parts.append(' ')

            if renderer.show_changes:
                if change_type == 'added':
                    parts.append(renderer.color_change_added('+'))
                elif change_type == 'modified':
                    parts.append(renderer.color_change_modified('~'))
                else:
                    parts.append(' ')
                parts.append(' ')

            if renderer.show_grid:
                parts.append(renderer.color_separator(BOX_V))
                parts.append(' ')

            # Content
            if hl_text is not None:
                content_part = hl_text
            elif opts.use_color:
                content_part = renderer.color(line, "38;5;231")
            else:
                content_part = line

            # Handle line highlighting (background color)
            if is_hl and opts.use_color:
                # Apply background highlight
                bg_code = "48;5;236"
                if hl_text is not None:
                    # Inject background into highlighted text
                    content_part = f"\x1b[{bg_code}m" + re.sub(r'\x1b\[0m', f'\x1b[0m\x1b[{bg_code}m', content_part)
                else:
                    content_part = f"\x1b[{bg_code};38;5;231m{line}\x1b[0m"
                # Pad to terminal width
                visible_len = len(re.sub(r'\x1b\[[^m]+m', '', content_part))
                content_width = renderer.term_width - gutter_w - (2 if renderer.show_grid else 0)
                if visible_len < content_width:
                    content_part += f"\x1b[{bg_code}m" + ' ' * (content_width - visible_len) + "\x1b[0m"

            # Handle wrapping
            if opts.wrap_mode == 'character' and not is_hl:
                content_width = renderer.term_width - gutter_w - (2 if renderer.show_grid else 0)
                # For now, just output the line (wrapping is complex with ANSI)
                pass

            parts.append(content_part)
            output_lines.append(''.join(parts))
        else:
            # Plain output (pipe mode or no decorations)
            if hl_text is not None:
                output_lines.append(hl_text)
            elif opts.use_color:
                output_lines.append(renderer.color(line, "38;5;231"))
            else:
                output_lines.append(line)

    # === Render bottom grid line ===
    if renderer.show_grid:
        bottom = renderer.render_grid_separator(gutter_w, BOX_BM)
        output_lines.append(bottom)

    # === Render rule between files ===
    if renderer.show_rule and not is_last_file:
        rule = renderer.render_rule(gutter_w)
        output_lines.append(rule)

    # Write output
    out = sys.stdout
    if opts.use_color or needs_decoration:
        for line in output_lines:
            out.write(line + '\n')
    else:
        # Plain text mode - exact cat behavior
        for i, line in enumerate(output_lines):
            out.write(line)
            if i < len(output_lines) - 1 or has_final_newline:
                out.write('\n')
        if not has_final_newline and output_lines:
            pass  # already handled above - no trailing newline

    out.flush()

