def process_show_all(data, notation='unicode', tab_width=4):
    """Process bytes with show-all mode. Returns string."""
    if tab_width <= 0:
        tab_width = 4
    result = []
    col = 0
    i = 0
    while i < len(data):
        b = data[i]
        if b == 0x0A:  # newline
            if notation == 'unicode':
                result.append('␊')
            else:
                result.append('^J')
            result.append('\n')
            col = 0
            i += 1
        elif b == 0x09:  # tab
            tab_stop = ((col // tab_width) + 1) * tab_width
            width = tab_stop - col
            if width == 1:
                result.append('↹')
            elif width >= 2:
                result.append('├' + '─' * (width - 2) + '┤')
            col += width
            i += 1
        elif b == 0x20:  # space
            result.append('·')
            col += 1
            i += 1
        elif b == 0x0D:  # CR
            if notation == 'unicode':
                result.append('␍')
            else:
                result.append('^M')
            col += 1
            i += 1
        elif b == 0x7F:  # DEL
            if notation == 'unicode':
                result.append('␡')
            else:
                result.append('^?')
            col += 1
            i += 1
        elif 0x00 <= b <= 0x1F:
            if notation == 'unicode':
                result.append(CTRL_UNICODE.get(b, f'\\x{b:02x}'))
                col += 1
            else:
                result.append(f'^{chr(0x40 + b)}')
                col += 2
            i += 1
        elif b >= 0x80:
            # UTF-8 sequence
            if b >= 0xF0:
                seq_len = 4
            elif b >= 0xE0:
                seq_len = 3
            elif b >= 0xC0:
                seq_len = 2
            else:
                seq_len = 1
            seq = data[i:i+seq_len]
            try:
                ch = seq.decode('utf-8')
                result.append(ch)
            except:
                result.append(f'\\x{b:02x}')
            col += 1
            i += seq_len
        else:
            result.append(chr(b))
            col += 1
            i += 1
    return ''.join(result)

