# Line range parsing
# ═══════════════════════════════════════════════════════

def parse_line_range(spec, total=None):
    """Parse line range spec. Returns (start, end) 1-based inclusive, or None."""
    if not spec:
        return None
    parts = spec.split(':')

    def resolve(s, total):
        if s == '' or s is None:
            return None
        s = str(s)
        if s.startswith('-') and not s[1:].startswith('-'):
            n = int(s)
            if total is not None:
                return total + n + 1
            return None
        if s.startswith('+'):
            return int(s)  # relative - handled by caller
        return int(s)

    if len(parts) == 1:
        n = resolve(parts[0], total)
        return (n, n) if n is not None else None

    if len(parts) == 2:
        s, e = parts
        start = resolve(s, total) if s else 1
        if e.startswith('+') and start is not None:
            end = start + int(e[1:])
        elif e == '':
            end = total
        else:
            end = resolve(e, total)
        return (start, end)

    if len(parts) == 3:
        s, e, c = parts
        ctx = int(c) if c else 0
        if e == '':
            # N::C
            n = resolve(s, total)
            if n is not None:
                return (n - ctx, n + ctx)
        else:
            # N:M:C
            n_s = resolve(s, total)
            n_e = resolve(e, total)
            if n_s is not None and n_e is not None:
                return (n_s - ctx, n_e + ctx)

    return None

def in_ranges(line_num, ranges, total):
    """Check if line_num is in any range."""
    if not ranges:
        return True
    for r in ranges:
        s, e = r
        if s is None:
            s = 1
        if e is None:
            e = total or 999999999
        if s <= line_num <= e:
            return True
    return False

# ═══════════════════════════════════════════════════════
# Git diff
# ═══════════════════════════════════════════════════════

def get_git_changes(filepath):
    """Returns dict of line_num (1-based) -> 'added'|'modified'"""
    try:
        abs_path = os.path.abspath(filepath)
        work_dir = os.path.dirname(abs_path) or '.'
        r = subprocess.run(
            ['git', 'diff', '--unified=0', '--no-color', 'HEAD', '--', abs_path],
            capture_output=True, text=True, cwd=work_dir
        )
        out = r.stdout
        if not out.strip():
            r = subprocess.run(
                ['git', 'diff', '--unified=0', '--no-color', '--', abs_path],
                capture_output=True, text=True, cwd=work_dir
            )
            out = r.stdout
    except Exception:
        return {}

    if not out.strip():
        return {}

    changes = {}
    cur_line = 0
    pending_removes = 0

    for line in out.split('\n'):
        if line.startswith('@@'):
            m = re.match(r'@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@', line)
            if m:
                cur_line = int(m.group(1))
                pending_removes = 0
        elif line.startswith('+++') or line.startswith('---'):
            pass
        elif line.startswith('+'):
            if pending_removes > 0:
                changes[cur_line] = 'modified'
                pending_removes -= 1
            else:
                changes[cur_line] = 'added'
            cur_line += 1
        elif line.startswith('-'):
            pending_removes += 1
        elif line.startswith(' '):
            pending_removes = 0
            cur_line += 1

    return changes

