# Style and options
# ═══════════════════════════════════════════════════════

DEFAULT_COMPONENTS = {'changes', 'grid', 'header-filename', 'numbers', 'snip'}
FULL_COMPONENTS = {'changes', 'grid', 'header-filename', 'header-filesize', 'numbers', 'rule', 'snip'}

def parse_style(s, base=None):
    if not s:
        return None
    s = s.strip()
    if s == 'default' or s == 'auto':
        return set(DEFAULT_COMPONENTS)
    if s == 'full':
        return set(FULL_COMPONENTS)
    if s == 'plain':
        return set()

    parts = [p.strip() for p in s.split(',') if p.strip()]
    # Check if modification mode (all have + or -)
    if all(p.startswith('+') or p.startswith('-') for p in parts):
        cur = set(base) if base else set(DEFAULT_COMPONENTS)
        for p in parts:
            name = p[1:]
            if name == 'header':
                name = 'header-filename'
            if p.startswith('+'):
                cur.add(name)
            else:
                cur.discard(name)
        return cur

    result = set()
    for p in parts:
        if p == 'default':
            result.update(DEFAULT_COMPONENTS)
        elif p == 'full':
            result.update(FULL_COMPONENTS)
        elif p == 'plain':
            pass
        elif p == 'header':
            result.add('header-filename')
        else:
            result.add(p)
    return result

class Opts:
    pass

def parse_args(argv):
    """Parse command-line arguments manually."""
    opts = Opts()

    # Defaults
    opts.files = []
    opts.subcommand = None
    opts.subcommand_args = []
    opts.language = None
    opts.fallback_syntax = None
    opts.show_all = False
    opts.nonprintable_notation = 'unicode'
    opts.binary_behavior = None  # 'no-printing' or 'as-text'
    opts.plain = 0
    opts.highlight_lines = []
    opts.file_names = []
    opts.diff = False
    opts.diff_context = 2
    opts.tabs = None
    opts.wrap = 'auto'
    opts.chop = False
    opts.terminal_width_arg = None
    opts.number = False
    opts.color = 'auto'
    opts.italic_text = 'never'
    opts.decorations = 'auto'
    opts.force_color = False
    opts.paging = 'auto'
    opts.pager = None
    opts.map_syntax = []
    opts.ignored_suffixes = []
    opts.theme = None
    opts.theme_light = None
    opts.theme_dark = None
    opts.list_themes = False
    opts.squeeze_blank = False
    opts.squeeze_limit = 1
    opts.strip_ansi = 'never'
    opts.style = None
    opts.line_ranges = []
    opts.list_languages = False
    opts.unbuffered = False
    opts.completion = None
    opts.diagnostic = False
    opts.quiet_empty = False
    opts.acknowledgements = False
    opts.set_terminal_title = False
    opts.help = False
    opts.short_help = False
    opts.version = False
    opts.show_config_file = False
    opts.show_cache_dir = False
    opts.generate_config = False

    i = 0
    end_of_options = False

    while i < len(argv):
        arg = argv[i]

        if end_of_options:
            opts.files.append(arg)
            i += 1
            continue

        if arg == '--':
            end_of_options = True
            i += 1
            continue

        # Check for cache subcommand (must be first positional arg)
        if arg == 'cache' and not opts.files and opts.subcommand is None:
            opts.subcommand = 'cache'
            opts.subcommand_args = argv[i+1:]
            break

        # Long options
        if arg.startswith('--'):
            if '=' in arg:
                key, val = arg.split('=', 1)
            else:
                key = arg
                val = None

            def get_val():
                nonlocal i, val
                if val is not None:
                    return val
                i += 1
                if i < len(argv):
                    return argv[i]
                return None

            if key == '--show-all' or key == '-A':
                opts.show_all = True
            elif key == '--nonprintable-notation':
                opts.nonprintable_notation = get_val()
            elif key == '--binary':
                opts.binary_behavior = get_val()
            elif key == '--plain':
                opts.plain += 1
            elif key == '--language':
                opts.language = get_val()
            elif key == '--fallback-syntax' or key == '--fallback-language':
                opts.fallback_syntax = get_val()
            elif key == '--highlight-line':
                opts.highlight_lines.append(get_val())
            elif key == '--file-name':
                opts.file_names.append(get_val())
            elif key == '--diff':
                opts.diff = True
            elif key == '--diff-context':
                v = get_val()
                opts.diff_context = int(v) if v else 2
            elif key == '--tabs':
                v = get_val()
                opts.tabs = int(v) if v is not None else None
            elif key == '--wrap':
                opts.wrap = get_val()
