# Style and options
# ═══════════════════════════════════════════════════════

DEFAULT_COMPONENTS = {'changes', 'grid', 'header-filename', 'numbers', 'snip'}
FULL_COMPONENTS = {'changes', 'grid', 'header-filename', 'header-filesize', 'numbers', 'rule', 'snip'}

def parse_style(s, base=None):
    if not s:
        return None
    s = s.strip()
    if s == 'default' or s == 'auto':
        return set(DEFAULT_COMPONENTS)
    if s == 'full':
        return set(FULL_COMPONENTS)
    if s == 'plain':
        return set()

    parts = [p.strip() for p in s.split(',') if p.strip()]
    # Check if modification mode (all have + or -)
    if all(p.startswith('+') or p.startswith('-') for p in parts):
        cur = set(base) if base else set(DEFAULT_COMPONENTS)
        for p in parts:
            name = p[1:]
            if name == 'header':
                name = 'header-filename'
            if p.startswith('+'):
                cur.add(name)
            else:
                cur.discard(name)
        return cur

    result = set()
    for p in parts:
        if p == 'default':
            result.update(DEFAULT_COMPONENTS)
        elif p == 'full':
            result.update(FULL_COMPONENTS)
        elif p == 'plain':
            pass
        elif p == 'header':
            result.add('header-filename')
        else:
            result.add(p)
    return result

