    """Generate the snip line for between non-adjacent ranges."""
    if has_numbers and has_grid:
        # ' ... │ content' where content has scissors
        prefix = ' ...' + BOX_V + ' '  # Actually need to check exact format
        # Observed: ' ... │ ' is 7 chars
        # Wait, we need the gutter chars too
        # Actually the snip line replaces the full line including gutter
        content_w = term_width - 7  # ' ... │ ' = 7 chars
        return ' ... ' + BOX_V + ' ' + _scissors(content_w)
    elif has_numbers:
        # ' ...' + scissors
        return ' ...' + _scissors_with_dashes(term_width - 4)
    else:
        # full scissors
        return _scissors_full(term_width)

def _scissors(width):
    """Make scissors pattern for given width."""
    if width <= 4:
        return '8<' + ' ' * (width - 2) if width >= 2 else ''
    half = (width - 2) // 2
    left_n = half // 2
    left = '─ ' * left_n
    right_w = width - len(left) - 2
    right_n = right_w // 2
    right = ' ─' * right_n
    result = left + '8<' + right
    diff = width - len(result)
    if diff > 0:
        result += '─' * diff
    return result[:width]

def _scissors_with_dashes(width):
    """Scissors starting with dashes (numbers-only mode)."""
    return _scissors(width)

def _scissors_full(width):
    """Full-width scissors (no prefix)."""
    # Pattern: '─ '*N + '8<' + ' ─'*M
    half = (width - 2) // 2
    n = half // 2
    left = '─ ' * n
    right_w = width - len(left) - 2
    m = right_w // 2
    right = ' ─' * m
    result = left + '8<' + right
    diff = width - len(result)
    if diff > 0:
        result += '─' * diff
    return result[:width]

