# Language detection
# ═══════════════════════════════════════════════════════

def detect_language(filename, map_syntax=None, fallback=None, content=None):
    """Detect language from filename/content."""
    # Check syntax mappings first
    if map_syntax and filename:
        import fnmatch
        basename = os.path.basename(filename)
        for pattern, lang in map_syntax:
            if fnmatch.fnmatch(basename, pattern) or fnmatch.fnmatch(filename, pattern):
                return lang

    if filename:
        basename = os.path.basename(filename)
        # Check exact name matches and extension matches
        for line in LANGUAGE_LIST.strip().split('\n'):
            if ':' not in line:
                continue
            name, exts = line.split(':', 1)
            for ext in exts.split(','):
                ext = ext.strip()
                if not ext:
                    continue
                if ext.startswith('/') or '**' in ext or '*' in ext:
                    # Path glob - skip for now
                    continue
                if ext.startswith('.'):
                    if basename == ext[1:] or basename == ext:
                        return name
                else:
                    if basename == ext:
                        return name

        # Try extension
        if '.' in basename:
            ext = basename.rsplit('.', 1)[1].lower()
            for line in LANGUAGE_LIST.strip().split('\n'):
                if ':' not in line:
                    continue
                name, exts = line.split(':', 1)
                for e in exts.split(','):
                    e = e.strip().lstrip('.')
                    if '/' in e or '*' in e:
                        continue
                    if e.lower() == ext:
                        return name

    # Try shebang
    if content and len(content) > 2 and content[:2] == b'#!':
        first_line = content.split(b'\n', 1)[0].decode('utf-8', errors='replace')
        if 'python' in first_line:
            return 'Python'
        if 'bash' in first_line or '/sh' in first_line:
            return 'Bourne Again Shell (bash)'
        if 'ruby' in first_line:
            return 'Ruby'
        if 'perl' in first_line:
            return 'Perl'
        if 'node' in first_line or 'nodejs' in first_line:
            return 'JavaScript (Babel)'

    return fallback

