        if use_deco and has_grid:
            if has_gutter:
                bot = BOX_H * gutter_w + BOX_BM + BOX_H * (term_w - gutter_w - 1)
            else:
                bot = BOX_H * term_w
            out.write(colorf(bot, '38;5;246', use_color) + '\\n')'''

if old_bot in content:
    content = content.replace(old_bot, new_bot)
    print("Fixed bottom grid")
else:
    print("Bottom grid not found!")

with open('/workspace/bat.py', 'w') as f:
    f.write(content)
